def respond(self, obj):
        """Gives a response JSON(P) message"""
        try:
            if self.content_type == "application/json":
                return self.json_response(obj)
            if self.content_type == "application/json-patch+json":
                return self.json_patch_response(obj)
            if self.content_type == "application/merge-patch+json":
                return self.json_merge_patch_response(obj)
            if self.content_type == "text/plain":
                return self.text_response(obj)
        except TypeError:
            return self.json_response(obj)

